                raise FloatingPointError(
                    "non-finite value encountered during d2 pinball score"
                )
            if prefix_sum >= threshold:
                q = value
                break
    except (OverflowError, ValueError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during d2 pinball score"
        ) from exc
    if q is None or not math.isfinite(q):
        raise FloatingPointError(
            "non-finite value encountered during d2 pinball score"
        )

    model_terms = []
    baseline_terms = []
    for i in range(n):
        try:
            d = t[i] - p[i]
            if d >= 0:
                model_loss = a * d
            else:
                model_loss = (a - 1.0) * d
            d0 = t[i] - q
